package eval

import (
	"encoding/json"
	"fmt"
	"os"
)

// Dataset represents the format for benchmarks B1-B5.
type Dataset struct {
	ID        string `json:"id"`
	Benchmark string `json:"benchmark"`
	Tasks     []Task `json:"tasks"`
}

type Task struct {
	ID       string `json:"id"`
	Question string `json:"question,omitempty"`
	// For B1, it might contain the original request and target output
	OriginalRequest string `json:"original_request,omitempty"`
	TargetOutput    string `json:"target_output,omitempty"`
}

func LoadDataset(path string) (*Dataset, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("reading dataset: %w", err)
	}

	var dataset Dataset
	if err := json.Unmarshal(data, &dataset); err != nil {
		return nil, fmt.Errorf("unmarshaling dataset: %w", err)
	}

	return &dataset, nil
}

package eval

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

type Result struct {
	Timestamp time.Time   `json:"timestamp"`
	Benchmark string      `json:"benchmark"`
	DatasetID string      `json:"dataset_id"`
	TaskID    string      `json:"task_id"`
	Query     string      `json:"query,omitempty"`
	Matches   []string    `json:"matches,omitempty"` // Episode IDs or snippets
	Metrics   interface{} `json:"metrics,omitempty"`
}

type Store struct {
	path string
	file *os.File
	enc  *json.Encoder
}

func NewStore(dir string) (*Store, error) {
	if err := os.MkdirAll(dir, 0755); err != nil {
		return nil, fmt.Errorf("creating eval result dir: %w", err)
	}

	resultPath := filepath.Join(dir, "results.jsonl")
	f, err := os.OpenFile(resultPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return nil, fmt.Errorf("opening eval result file: %w", err)
	}

	return &Store{
		path: resultPath,
		file: f,
		enc:  json.NewEncoder(f),
	}, nil
}

func (s *Store) Record(r Result) error {
	r.Timestamp = time.Now()
	if err := s.enc.Encode(r); err != nil {
		return fmt.Errorf("encoding result: %w", err)
	}
	return nil
}

func (s *Store) Close() error {
	return s.file.Close()
}

package eval

import (
	"context"
	"fmt"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

type Runner struct {
	store *Store
	idx   *index.EpisodeIndex
}

func NewRunner(store *Store, idx *index.EpisodeIndex) *Runner {
	return &Runner{
		store: store,
		idx:   idx,
	}
}

func (r *Runner) RunB2(ctx context.Context, dataset *Dataset) error {
	if dataset.Benchmark != "B2" {
		return fmt.Errorf("expected B2 benchmark dataset, got %s", dataset.Benchmark)
	}

	for _, task := range dataset.Tasks {
		// B2 baseline: query FTS index with the question
		results, err := r.idx.SearchEpisodes(ctx, task.Question)
		if err != nil {
			return fmt.Errorf("searching for task %s: %w", task.ID, err)
		}

		var matches []string
		for _, res := range results {
			matches = append(matches, res.EpisodeID)
		}

		// Record top retrieved results (let's say all returned by search, which is usually limited or we can take top N)
		// Usually SearchEpisodes returns top 10 or so depending on its implementation.

		err = r.store.Record(Result{
			Benchmark: "B2",
			DatasetID: dataset.ID,
			TaskID:    task.ID,
			Query:     task.Question,
			Matches:   matches,
		})
		if err != nil {
			return fmt.Errorf("recording result for task %s: %w", task.ID, err)
		}
	}

	return nil
}

package eval

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

func TestDatasetLoading(t *testing.T) {
	tmpDir := t.TempDir()
	datasetPath := filepath.Join(tmpDir, "b2.json")

	dataset := Dataset{
		ID:        "b2-test-1",
		Benchmark: "B2",
		Tasks: []Task{
			{ID: "t1", Question: "how do I configure?"},
		},
	}

	data, _ := json.Marshal(dataset)
	os.WriteFile(datasetPath, data, 0644)

	loaded, err := LoadDataset(datasetPath)
	if err != nil {
		t.Fatalf("LoadDataset failed: %v", err)
	}

	if loaded.Benchmark != "B2" || len(loaded.Tasks) != 1 {
		t.Errorf("Unexpected dataset content")
	}
}

func TestStore(t *testing.T) {
	tmpDir := t.TempDir()
	store, err := NewStore(tmpDir)
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}

	err = store.Record(Result{
		Benchmark: "B2",
		DatasetID: "ds1",
		TaskID:    "t1",
	})
	if err != nil {
		t.Errorf("Record failed: %v", err)
	}

	store.Close()

	data, err := os.ReadFile(filepath.Join(tmpDir, "results.jsonl"))
	if err != nil {
		t.Fatalf("Failed reading results: %v", err)
	}

	if len(data) == 0 {
		t.Errorf("Expected results, got empty file")
	}
}

func TestRunnerB2(t *testing.T) {
	tmpDir := t.TempDir()
	dbPath := filepath.Join(tmpDir, "episodes.db")

	// Create an index
	idx, err := index.NewIndex(dbPath)
	if err != nil {
		t.Fatalf("NewIndex failed: %v", err)
	}
	defer idx.Close()

	// Index a dummy episode
	err = idx.IndexEpisode(context.Background(), &index.EpisodeDoc{
		EpisodeID:    "ep1",
		Date:         time.Now(),
		SessionID:    "sess1",
		Snippet:      "configure the system with config.yaml",
		FilesTouched: "config.yaml",
	})
	if err != nil {
		t.Fatalf("IndexEpisode failed: %v", err)
	}

	store, _ := NewStore(tmpDir)
	defer store.Close()

	runner := NewRunner(store, idx)

	dataset := &Dataset{
		ID:        "b2-test",
		Benchmark: "B2",
		Tasks: []Task{
			{ID: "t1", Question: "configure"},
		},
	}

	err = runner.RunB2(context.Background(), dataset)
	if err != nil {
		t.Fatalf("RunB2 failed: %v", err)
	}

	// Verify result store has output
	store.Close()
	data, _ := os.ReadFile(filepath.Join(tmpDir, "results.jsonl"))
	var res Result
	if err := json.Unmarshal(data, &res); err != nil {
		t.Fatalf("unmarshal result failed: %v", err)
	}

	if len(res.Matches) == 0 || res.Matches[0] != "ep1" {
		t.Errorf("Expected ep1 match, got: %v", res.Matches)
	}
}

